def card(title,text,ico='file',url=None):
 tag='a' if url else 'article';link=(' href="'+url+'"') if url else ''
 return '<'+tag+' class="card '+('link-card' if url else '')+'"'+link+'><div class="card-icon">'+icon(ico)+'</div>'+('<span class="arrow-corner">'+icon('arrow-up')+'</span>' if url else '')+'<h3>'+title+'</h3><p>'+text+'</p></'+tag+'>'
def section(t,d,b,id=''):return '<section class="section reveal"'+(' id="'+id+'"' if id else '')+'><div class="section-head"><div><h2>'+t+'</h2>'+('<p>'+d+'</p>' if d else '')+'</div></div>'+b+'</section>'
def callout(t,b,rose=False):return '<aside class="callout '+('rose' if rose else '')+'">'+icon('info')+'<div><strong>'+t+'</strong><p>'+b+'</p></div></aside>'
def explain(items):return '<div class="explain-list">'+''.join('<div class="explain">'+icon(i)+'<div><strong>'+a+'</strong><p>'+b+'</p></div></div>' for i,a,b in items)+'</div>'
